import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused ConvTranspose2d + Scalar Multiplication + Global Average Pooling
kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_conv_gap_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    float multiplier,
    int in_channels,
    int out_channels,
    int batch_size,
    int input_height,
    int input_width,
    int output_height,
    int output_width
) {
    // ConvTranspose2d implementation
    int h_out = blockIdx.y * stride + (blockIdx.y == 0 ? 0 : output_padding) - padding;
    int w_out = blockIdx.z * stride + (blockIdx.z == 0 ? 0 : output_padding) - padding;

    float sum = 0.0f;

    for (int c_in = 0; c_in < in_channels; ++c_in) {
        for (int i = 0; i < kernel_size; ++i) {
            for (int j = 0; j < kernel_size; ++j) {
                int h_in = h_out + i;
                int w_in = w_out + j;

                if (h_in >= 0 && h_in < input_height && w_in >= 0 && w_in < input_width) {
                    float input_val = input[blockIdx.x * in_channels * input_height * input_width +
                                         c_in * input_height * input_width +
                                         h_in * input_width +
                                         w_in];

                    float weight_val = weight[c_in * out_channels * kernel_size * kernel_size +
                                            blockIdx.y * kernel_size * kernel_size +
                                            i * kernel_size +
                                            j];

                    sum += input_val * weight_val;
                }
            }
        }
    }

    if (bias) sum += bias[blockIdx.y];
    sum *= multiplier;

    // Write conv output and immediately compute GAP
    atomicAdd(&output[blockIdx.x * out_channels + blockIdx.y], sum / (output_height * output_width));
}

torch::Tensor fused_conv_gap_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    float multiplier,
    int output_height,
    int output_width
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int out_channels = weight.size(1);

    auto output = torch::zeros({batch_size, out_channels, 1, 1}, input.options());

    dim3 grid(batch_size, output_height, output_width);
    fused_conv_gap_kernel<<<grid, out_channels>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        kernel_size,
        stride,
        padding,
        output_padding,
        multiplier,
        in_channels,
        out_channels,
        batch_size,
        input.size(2),
        input.size(3),
        output_height,
        output_width
    );

    return output;
}
"""

cpp_code = "torch::Tensor fused_conv_gap_cuda(torch::Tensor, torch::Tensor, torch::Tensor, int, int, int, int, float, int, int);"

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=cpp_code,
    cuda_sources=kernel_code,
    functions=['fused_conv_gap_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, multiplier):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding
        )
        self.multiplier = multiplier
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding

    def forward(self, x):
        input_height, input_width = x.size()[2:]
        output_height = (input_height - 1) * self.stride + self.output_padding + self.kernel_size - 2 * self.padding
        output_width = (input_width - 1) * self.stride + self.output_padding + self.kernel_size - 2 * self.padding

        return fused_ops.fused_conv_gap_cuda(
            x,
            self.conv_transpose.weight,
            self.conv_transpose.bias,
            self.kernel_size,
            self.stride,
            self.padding,
            self.output_padding,
            self.multiplier,
            output_height,
            output_width
        )
